std::set<std::tuple<std::string,std::string,std::string,std::int64_t>> sourcekeys;for(std::size_t i=0;i<p.rows.size();++i){auto&r=p.rows[i];if(!sourcekeys.insert({r.source_dataset_id,r.source_row_id,r.shot_id,r.pts}).second)throw std::runtime_error("duplicate immutable source row identity at joint row "+std::to_string(i));if(!finite_array(r.uv)||!std::isfinite(r.E)||!(r.E>0)||!std::isfinite(r.station)||r.station<0||r.station>1||!std::isfinite(r.row)||r.row<0||r.row>1079)throw std::runtime_error("invalid joint observation/nuisance");if(!r.active)continue;auto l=model.layout(model.shot_map.at(r.shot_id),r.material,r.path,r.pts);if(r.kind==1&&!model.materials[r.material].paths[r.path].physical_point)throw std::runtime_error("entity corner may not become a sliding station");}
