for(const auto&q:j.value("queries",eventio::Json::array())){auto i=q.at("row_index").get<std::size_t>();auto curve=std::make_shared<JointQuery>();curve->alpha=q.at("alpha").get<std::vector<double>>();curve->uv=q.at("native_uv").get<std::vector<Vec2<double>>>();curve->nx=q.value("numerator_x",std::vector<double>{});curve->ny=q.value("numerator_y",std::vector<double>{});curve->den=q.value("denominator",std::vector<double>{});curve->origin=q.value("alpha_origin",0.);curve->scale=q.value("alpha_scale",1.);if(curve->alpha.size()<2||curve->alpha.size()!=curve->uv.size()||!(curve->scale>0))throw std::runtime_error("invalid original profile query");for(std::size_t k=1;k<curve->alpha.size();++k)if(!(curve->alpha[k]>curve->alpha[k-1]))throw std::runtime_error("nonmonotonic finite profile query");p.rows.at(i).query=curve;p.rows.at(i).normal=q.at("normal").get<Vec2<double>>();}
